import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import '../../core/routes/app_routes.dart';import '../../core/utils/formatters.dart';import '../../models/invoice.dart';import '../../models/tax_assessment.dart';import '../../services/invoice_service.dart';import '../../services/tax_assessment_service.dart';import '../../widgets/empty_state.dart';import '../../widgets/error_state.dart';
class AssessmentsScreen extends StatefulWidget {final InvoiceService invoices;final TaxAssessmentService assessments;const AssessmentsScreen({super.key,required this.invoices,required this.assessments});@override State<AssessmentsScreen> createState()=>_AssessmentsScreenState();}
class _AssessmentsScreenState extends State<AssessmentsScreen>{bool history=false,loading=false;String? error;List<Invoice> invoices=[];List<TaxAssessment> assessments=[];final selected=<int>{};final name=TextEditingController();@override void initState(){super.initState();reload();}@override void dispose(){name.dispose();super.dispose();}
 Future<void> reload()async{setState((){loading=true;error=null;});try{final i=await widget.invoices.list(pendingOnly:true);final a=await widget.assessments.list();if(mounted)setState((){invoices=i;assessments=a;selected.clear();});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> assess()async{if(selected.isEmpty||name.text.trim().isEmpty)return;setState(()=>loading=true);try{final a=await widget.assessments.create(name.text.trim(),selected.toList());if(mounted)context.go(AppRoutes.assessmentDetail(a.id));}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Apuração de impostos'),leading:IconButton(icon:const Icon(Icons.home),onPressed:()=>context.go(AppRoutes.home)),actions:[TextButton(onPressed:()=>setState(()=>history=!history),child:Text(history?'Selecionar notas':'Impostos apurados'))]),body:loading?const Center(child:CircularProgressIndicator()):error!=null?ErrorState(message:error!,onRetry:reload):ListView(padding:const EdgeInsets.all(16),children:[if(history)...[if(assessments.isEmpty)const EmptyState(message:'Nenhuma apuração registrada.'),...assessments.map((a)=>Card(child:ListTile(title:Text(a.name),subtitle:Text('${a.invoiceCount} notas'),trailing:const Icon(Icons.chevron_right),onTap:()=>context.go(AppRoutes.assessmentDetail(a.id)))))]else...[TextField(controller:name,decoration:const InputDecoration(labelText:'Identificação da apuração')),CheckboxListTile(value:invoices.isNotEmpty&&selected.length==invoices.length,title:const Text('Selecionar todas as notas'),onChanged:(v)=>setState((){selected.clear();if(v==true)selected.addAll(invoices.map((e)=>e.id!));})),if(invoices.isEmpty)const EmptyState(message:'Nenhuma nota pendente.'),...invoices.map((x)=>CheckboxListTile(value:selected.contains(x.id),title:Text('NF ${x.number} — ${x.supplier}'),subtitle:Text('${Formatters.date(x.issueDate)} · ${Formatters.money(x.grossTotal)}'),onChanged:(v)=>setState((){if(v==true){selected.add(x.id!);}else{selected.remove(x.id);}}))),const SizedBox(height:12),FilledButton(onPressed:selected.isEmpty?null:assess,child:const Text('Apurar impostos'))],const SizedBox(height:20),const Text('Observação: os valores destacados nas notas de entrada não representam, isoladamente, imposto devido.',style:TextStyle(fontStyle:FontStyle.italic))]));}
